  it('post181: locks wrangler.toml sha256 UPPERCASE', () => { expect(sha256('wrangler.toml').toUpperCase()).toBe('95B11779A88F0544F3561EEA67994A0B0B874D7B8776579189FA7142FA0473F8'); });
